const input = $input.first().json || {};
const headers = input.headers || {};
const body = input.body || input;
const secret = String($env.N8N_WEBHOOK_SECRET || '').trim();
const incoming = String(headers['x-mdoctor-webhook-secret'] || headers['X-MDoctor-Webhook-Secret'] || body.webhook_secret || '').trim();
if (secret && incoming !== secret) throw new Error('Invalid webhook secret');

const flowEnv = String($env.FLOW_ENV || 'staging').toLowerCase();
if (flowEnv !== 'staging') throw new Error('FLOW_ENV must be staging');

const backendUrl = String($env.BACKEND_URL_STAGING || $env.BACKEND_BASE_URL || 'https://mdoctor-backend-staging-staging.up.railway.app').replace(/\/$/, '');
if (backendUrl.includes('web-production')) throw new Error('Backend staging must not be production web');

const atendimentoId = String(body.atendimento_id || body.atendimentoId || '').trim();
if (!atendimentoId) throw new Error('atendimento_id required');

const channel = String(body.channel || 'whatsapp').trim().toLowerCase();
const correlationId = headers['x-correlation-id'] || headers['X-Correlation-Id'] || body.correlation_id || `delivery-${atendimentoId}`;
const idempotencyKey = String(
  headers['idempotency-key'] ||
  headers['Idempotency-Key'] ||
  body.idempotency_key ||
  `delivery:${atendimentoId}:${channel}`
);

return [{
  json: {
    backendUrl,
    atendimentoId,
    channel,
    correlationId,
    idempotencyKey,
    headers: {
      'Content-Type': 'application/json',
      'X-MDoctor-Webhook-Secret': secret,
      'X-Correlation-Id': correlationId,
      'Idempotency-Key': idempotencyKey,
      'X-N8N-Workflow': 'prescription-delivery-staging'
    },
    body: { channel }
  }
}];
